from fastapi import FastAPI, Request, HTTPException
from motor.motor_asyncio import AsyncIOMotorClient
from pydantic import BaseModel
import boto3
import json
import os

app = FastAPI()

# MongoDB connection for user session/metadata store
MONGO_URI = os.getenv("MONGO_URI", "mongodb://localhost:27017")
S3_BUCKET = os.getenv("DATA_BUCKET", "sensitive-reports-prod")
VPCE_ID = os.getenv("VPCE_ID", "vpce-0a1b2c3d4e5f67890")

client = AsyncIOMotorClient(MONGO_URI)
db = client.reporting_service

s3 = boto3.client("s3", endpoint_url=os.getenv("S3_ENDPOINT"))

class ReportQuery(BaseModel):
    department: str
    fiscal_year: str
    include_archived: bool = False


@app.post("/api/v1/reports/search")
async def search_reports(query: ReportQuery, request: Request):
    """Search reports by department and fiscal year, then fetch from S3."""

    # Build MongoDB filter from user input
    mongo_filter = {
        "department": query.department,
        "fiscal_year": query.fiscal_year
    }

    if query.include_archived:
        mongo_filter["status"] = {"$in": ["active", "archived"]}
    else:
        mongo_filter["status"] = "active"

    # Query MongoDB for matching report metadata
    cursor = db.report_metadata.find(mongo_filter)
    reports = await cursor.to_list(length=100)

    if not reports:
        raise HTTPException(status_code=404, detail="No reports found")

    # Fetch actual report data from S3
    results = []
    for report in reports:
        try:
            s3_key = report.get("s3_key")
            if s3_key:
                obj = s3.get_object(Bucket=S3_BUCKET, Key=s3_key)
                content = obj["Body"].read().decode("utf-8")
                results.append({
                    "report_id": str(report["_id"]),
                    "title": report.get("title"),
                    "department": report.get("department"),
                    "content_preview": content[:500]
                })
        except Exception as e:
            results.append({
                "report_id": str(report["_id"]),
                "title": report.get("title"),
                "error": f"Failed to retrieve: {str(e)}"
            })

    return {"count": len(results), "reports": results}


@app.post("/api/v1/reports/lookup")
async def lookup_report(request: Request):
    """Direct report lookup by arbitrary filter - internal API."""
    body = await request.json()

    # WARNING: passes raw JSON body as MongoDB query filter
    # Intended for internal service-to-service calls only
    user_filter = body.get("filter", {})
    projection = body.get("projection", {"s3_key": 1, "title": 1, "department": 1})

    cursor = db.report_metadata.find(user_filter, projection)
    reports = await cursor.to_list(length=50)

    # Retrieve S3 objects for matched reports
    results = []
    for report in reports:
        s3_key = report.get("s3_key")
        if s3_key:
            try:
                obj = s3.get_object(Bucket=S3_BUCKET, Key=s3_key)
                content = obj["Body"].read().decode("utf-8")
                results.append({
                    "report_id": str(report["_id"]),
                    "title": report.get("title"),
                    "s3_key": s3_key,
                    "content_preview": content[:1000]
                })
            except Exception:
                pass

    return {"results": results}


@app.get("/health")
async def health():
    return {"status": "ok", "vpce": VPCE_ID}
